package com.adhook.plugin;

import org.junit.Test;

import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.List;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * Cross-language market contract: the index fixture is generated by tools/plugin_package.py.
 * It must parse with the production Java index parser and bind to the packaged zip.
 */
public class PluginMarketContractTest {

    private static byte[] resource(String name) throws Exception {
        try (InputStream input = PluginMarketContractTest.class.getResourceAsStream(name)) {
            assertNotNull("missing test fixture: " + name, input);
            return input.readAllBytes();
        }
    }

    private static String sha256(byte[] data) throws Exception {
        MessageDigest digest = MessageDigest.getInstance("SHA-256");
        byte[] result = digest.digest(data);
        StringBuilder hex = new StringBuilder(result.length * 2);
        for (byte value : result) hex.append(String.format(java.util.Locale.ROOT, "%02x", value & 0xff));
        return hex.toString();
    }

    @Test public void pythonGeneratedIndexParsesAndBindsToSignedZip() throws Exception {
        String indexText = new String(resource("/plugins/market-index.json"), StandardCharsets.UTF_8);
        PluginMarketIndex index = PluginMarketIndex.parse(indexText);
        assertNotNull("market index must parse", index);
        assertEquals(1, index.size());
        PluginMarketEntry entry = index.find("com.adhook.plugin.sample");
        assertNotNull(entry);
        PluginMarketRelease release = entry.getRelease();
        assertNotNull(release);
        assertNotNull("nested publisher required", release.getPublisherKeyId());
        assertTrue(release.hasPublisher());
        assertEquals("plugin.sig keyId", release.getPublisherKeyId(),
                PluginSignature.keyId(release.publisherPublicKeyDer()));

        byte[] zip = resource("/plugins/sample-plugin.zip");
        String zipSha = sha256(zip);
        assertEquals(release.getSha256(), zipSha);

        java.io.File temporary = java.io.File.createTempFile("adhook-market-fixture", ".zip");
        try {
            java.nio.file.Files.write(temporary.toPath(), zip);
            PluginPackage pkg = PluginZip.read(temporary);
            assertTrue("signature must verify", PluginSignature.verify(pkg));
            assertEquals(InstallError.OK,
                    PluginMarketInstallPolicy.verify(pkg.manifest, entry, zipSha));
            assertEquals(release.getPublisherKeyId(), pkg.manifest.getPublisherKeyId());
            assertTrue(java.util.Arrays.equals(release.publisherPublicKeyDer(),
                    pkg.manifest.publisherPublicKeyDer()));
            List<String> listedTargets = entry.getTargets();
            assertEquals(1, listedTargets.size());
            assertEquals("com.example.host", listedTargets.get(0));
        } finally {
            temporary.delete();
        }
    }
}
